internal sealed class LatticeBRSTCartanChargeCharacterDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original physical charge fibers classified by the entire Cartan character",
        H("Original physical charge fibers classified by the entire Cartan character"), Blocks(
            Paragraph(Text("This document describes the original candidate under native repair. Complete identity/axiom validation, Blueprint rendering, freeze, registration and required-check acceptance remain pending. The full Monster → VOA/CFT/anomaly/fusion/string/AdS goal remains ACTIVE INCOMPLETE.")),
            Paragraph(Text("Let D : LatticeData be the original integral symmetric even lattice datum and let r = D.rank. Retain h26 : D.rank = 26 and an arbitrary H : Matrix (Fin D.rank) (Fin D.rank) Complex with BOTH hHG : H * gramComplex D = 1 and hGH : gramComplex D * H = 1. There is no positivity, realness, signature, unimodularity, perfectness, HPL-invariance or finite-dimensionality assumption on the whole physical image.")),
            Paragraph(Text("Write C = Cohomology D H h26 hHG hGH for the original global BRST quotient. The incoming boundary primitives remain arbitrary elements of the original State D, in both slots of the already descended current. No physical, charge, energy or ghost-number restriction is imposed on those primitives. All operators, quotient maps and the physical Lie bracket are the original suppliers.")),
            Paragraph(Text("The original physical state submodule consists of x : State D with totalCharge D H x = 0, ghostB D 0 x = 0, tensorNumber D x = x and totalL0 D H x = 0. Its existing linear physicalClass has image Ph = physicalImage D H h26 hHG hGH. With the existing charge inclusion i_beta and projection pi_beta, the existing fiber is F_beta = Ph ∩ range(i_beta) = physicalChargeFiber D H h26 hHG hGH beta, a submodule of C.")),
            Paragraph(Text("For every beta : Charge D = (Fin D.rank → Int), define gamma_D(v,beta) = Σ_i v_i * (bilinear D (unitCharge D i) beta : Complex) for every complex vector v : Fin D.rank → Complex. Let h(v) = cartanPhysicalImage D H h26 hHG hGH v : Ph. The exact assertion is (c : C) ∈ F_beta iff, for EVERY complex v, [h(v), c] = gamma_D(v,beta) • c. Both beta = 0 and c = 0 are included; c ranges over the entire original Ph.")),
            Paragraph(Text("Canonical declaration and source declaration: D5.S3.VertexAlgebra.Lattice.PhysicalLie.LatticeBRSTCartanChargeCharacter.mem_physicalChargeFiber_iff_cartan_adjoint. The two private helpers support this one theorem and receive no separate Describe registration.")),
            Describe.Lean(DescribeId.Create("latticebrstcartanchargecharacter-mem-physicalchargefiber-iff-cartan-adjoint"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTCartanChargeCharacter.mem_physicalChargeFiber_iff_cartan_adjoint"),
                H("All original charges are exactly the simultaneous Cartan characters"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Source notation and complete enclosing context (verbatim immutable source prefix, including both private helper proofs):\n/- GID: D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTCartanChargeCharacter\n   generality: I\n   mirror-B: D5/B/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTCartanChargeCharacter\n   mirror-E: none(waiver:source-candidate-not-enrolled)\n   anchors: []\n   utility: none\n   digest: Intrinsic classification of original physical charge fibers by all actual Cartan adjoints. -/\n\nimport D5.S3.VertexAlgebra.Lattice.PhysicalLie.LatticeBRSTPhysicalChargeFiber\nimport Batteries.Tactic.OpenPrivate\n\n/-!\nSOURCE_ONLY_UNCOMPILED. No native elaboration, kernel, axiom-closure or typed\naudit check has been attempted for this source package.\n\nThe carrier, class map, charge fiber and Lie bracket are the original supplier\ndefinitions. Both quotient slots still allow primitives in ALL original\nState D. Every charge, including zero, is covered. The complex inverse H is\narbitrary subject to BOTH original inverse-Gram equations.\n\nReuse: NeutralPhysicalCartan.project_physical supplies all FOUR physical\nequations for each literal charge projection; ChargeCohomology supplies finite\ncharge support, reconstruction and actual quotient inclusion/projection;\nNeutralPhysicalCartan.cartan_adjoint supplies the forward action, with no\nnonzero-charge restriction. No projector/Q/ghost-number commutation is reproved.\n\nAttribution: the original lattice-field suppliers retain Bakalov--Kac,\nCarnahan and Kytölä attribution, and the BRST/current suppliers retain\nBecchi--Rouet--Stora--Tyutin, Kato--Ogawa and Lian--Zuckerman attribution.\nFinite sums, complex linear algebra, integer casts and quotient maps use\nMathlib; existing private suppliers are opened with Batteries.Tactic.OpenPrivate.\nThis file adds the finite physical-component converse and full Cartan-character\nseparation. It makes no literature-novelty claim and constructs no Weyl\nautomorphism, Monster realization or completed string theory.\n-/\n\nset_option autoImplicit false\nset_option relaxedAutoImplicit false\nset_option backward.isDefEq.respectTransparency true\nset_option maxRecDepth 4096\n\nnoncomputable section\nopen scoped BigOperators\n\nopen private project_physical from\n  D5.S3.VertexAlgebra.Lattice.PhysicalLie.LatticeBRSTNeutralPhysicalCartan\nopen private chargeProject_mem chargeProject_on_fixed from\n  D5.S3.VertexAlgebra.Lattice.PhysicalLie.LatticeBRSTChargeCohomology\nopen private bilinear_unit from\n  D5.S3.VertexAlgebra.LatticeFiniteNegativeGeneration\n\nnamespace D5.S3.VertexAlgebra.Lattice.PhysicalLie.LatticeBRSTCartanChargeCharacter\n\nopen LatticeGeneratingFieldLocality (LatticeData Charge bilinear unitCharge)\nopen LatticeSugawaraCurrents (gramComplex)\nopen LatticeMatterGhostCoupling (State)\nopen LatticeRelativeMassShell (fixedMomentum)\nopen LatticeQuartetContraction (chargeProject)\nopen LatticeBRSTCohomologyField (Cohomology cycles classOf)\nopen LatticeBRSTCohomologyBVSecondOrder (cohomologyCurrent)\nopen LatticeBRSTPhysicalLie (physicalStates physicalClass physicalImage)\nopen LatticeBRSTChargeCohomology\n  (inclusion projection cycleInclusion cycleProjection chargeSupport sum_chargeProject)\nopen LatticeBRSTNeutralPhysicalCartan\n  (gamma cartanClass cartanPhysicalImage cartan_adjoint)\nopen LatticeBRSTPhysicalChargeFiber (physicalChargeFiber)\n\n/- The left inverse separates charge vectors. The public theorem below keeps\nboth inverses because its original quotient and physical bracket require them. -/\nprivate theorem gamma_separates_charges\n    (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ)\n    (hHG : H * gramComplex D = 1) (p q : Charge D)\n    (h : ∀ v : Fin D.rank → ℂ, gamma D v p = gamma D v q) : p = q := by\n  classical\n  have hrow (i : Fin D.rank) :\n      (bilinear D (unitCharge D i) p : ℂ) =\n        (bilinear D (unitCharge D i) q : ℂ) := by\n    simpa [gamma, ite_mul] using\n      h (fun j => if j = i then (1 : ℂ) else 0)\n  have hgram :\n      (gramComplex D).mulVec (fun i => (p i : ℂ)) =\n        (gramComplex D).mulVec (fun i => (q i : ℂ)) := by\n    funext i\n    simpa [Matrix.mulVec, dotProduct, gramComplex, bilinear_unit,\n      Int.cast_sum, Int.cast_mul] using hrow i\n  have hcoordinates :=\n    congrArg (fun w : Fin D.rank → ℂ => H.mulVec w) hgram\n  simp only [Matrix.mulVec_mulVec, hHG, Matrix.one_mulVec] at hcoordinates\n  funext i\n  exact (Int.cast_injective (α := ℂ)) (congrFun hcoordinates i)\n\nvariable (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ)\n  (h26 : D.rank = 26) (hHG : H * gramComplex D = 1)\n  (hGH : gramComplex D * H = 1)\n\nlocal notation \"C\" => Cohomology D H h26 hHG hGH\nlocal notation \"Ph\" => physicalImage D H h26 hHG hGH\nlocal notation \"J\" => cohomologyCurrent D H h26 hHG hGH\n\n/- Identification in the EXISTING quotient. The literal projector's action on\na fixed-charge state is reused; no new descent or commutation is asserted. -/\nprivate theorem chargeProjection_physicalClass (p q : Charge D)\n    (x : physicalStates D H) (hx : (x : State D) ∈ fixedMomentum D q) :\n    inclusion D H h26 hHG hGH p\n        (projection D H h26 hHG hGH p (physicalClass D H h26 hHG hGH x)) =\n      if q = p then physicalClass D H h26 hHG hGH x else 0 := by\n  classical\n  let u : cycles D H := ⟨(x : State D), x.property.1⟩\n  change classOf D H h26 hHG hGH\n      (cycleInclusion D H p (cycleProjection D H p u)) =\n    if q = p then classOf D H h26 hHG hGH u else 0\n  by_cases hqp : q = p\n  · rw [if_pos hqp]\n    apply congrArg (classOf D H h26 hHG hGH)\n    apply Subtype.ext\n    exact (chargeProject_on_fixed D p q (x : State D) hx).trans (if_pos hqp)\n  · rw [if_neg hqp]\n    have hz : cycleInclusion D H p (cycleProjection D H p u) = 0 := by\n      apply Subtype.ext\n      exact (chargeProject_on_fixed D p q (x : State D) hx).trans (if_neg hqp)\n    rw [hz, map_zero]\n\n/-- A class in the entire original physical Lie image lies in the literal\ncharge-beta fiber exactly when ALL actual Cartan adjoints have character beta.\nThis includes beta = 0 and the zero class. No homogeneous representative,\nprojection invariance premise, finite-dimensionality or root is assumed. -/\n")),
                    Paragraph(Text("Exact written theorem header through its outer assignment:\ntheorem mem_physicalChargeFiber_iff_cartan_adjoint (beta : Charge D) (c : Ph) :\n    (c : C) ∈ physicalChargeFiber D H h26 hHG hGH beta ↔\n      ∀ v : Fin D.rank → ℂ,\n        ⁅cartanPhysicalImage D H h26 hHG hGH v, c⁆ = gamma D v beta • c := by\n")),
                    Paragraph(Text("Exact converse representative and local component definitions:\n    obtain ⟨x, hx⟩ := c.property\n    -- Literal physical representatives of every charge component. All four\n    -- physical equations are supplied by the existing private theorem.\n    let xp (p : Charge D) : physicalStates D H :=\n      ⟨chargeProject p (x : State D), project_physical D H hHG hGH p x⟩\n    let component (p : Charge D) : Ph :=\n      ⟨physicalClass D H h26 hHG hGH (xp p), ⟨xp p, rfl⟩⟩\n\nExact local quotient projector definition:\n    let P (p : Charge D) : C →ₗ[ℂ] C :=\n      (inclusion D H h26 hHG hGH p).comp (projection D H h26 hHG hGH p)\n")),
                    Paragraph(Text("The forward implication applies NeutralPhysicalCartan.cartan_adjoint to hc.2, the inclusion-range part of membership in the existing fiber. It covers every charge without a nonzero-charge premise.")),
                    Paragraph(Text("For the converse choose an actual physical representative x with physicalClass(x) = c using c.property. Let S = chargeSupport D (x : State D), the finite support of this single original tensor state. For every charge p set x_p = chargeProject p x and c_p = physicalClass(x_p). The existing private NeutralPhysicalCartan.project_physical supplies ALL FOUR physical equations for each x_p. Existing sum_chargeProject reconstructs x = Σ_(p∈S) x_p first inside physicalStates through its subtype map, then c = Σ_(p∈S) c_p through the linear physicalClass. This establishes physical-component reconstruction without a finite-dimensional whole-Ph assumption.")),
                    Paragraph(Text("Each c_p belongs to the literal physical image and range(i_p). The existing quotient maps identify P_p(c) = c_p for P_p = i_p ∘ pi_p. The private helper chargeProjection_physicalClass passes chargeProject_on_fixed through the original cycle inclusion, cycle projection and class map to give P_p(c_q) = c_q if q = p and 0 otherwise. It is actually applied to x_q with chargeProject_mem in project_component.")),
                    Paragraph(Text("For p ∈ S, apply the original Cartan action to every actual component c_q, use the finite reconstruction and linearity of the original descended current and P_p, and eliminate the off-p summands. This gives P_p([h(v),c]) = gamma_D(v,p) • c_p. Applying P_p to the assumed simultaneous eigen-equation gives the same expression equal to gamma_D(v,beta) • c_p for every complex v.")),
                    Paragraph(Text("If c_p ≠ 0 in the original quotient C, subtraction gives (gamma_D(v,p) - gamma_D(v,beta)) • c_p = 0. The field-module law smul_eq_zero cancels the nonzero QUOTIENT component, proving equality of the two characters for every complex v. No cancellation of representatives is used.")),
                    Paragraph(Text("The private gamma_separates_charges helper evaluates the characters on every coordinate unit vector. Existing LatticeFiniteNegativeGeneration.bilinear_unit identifies the resulting integral bilinear values with the Gram rows, so gramComplex D * p_Complex = gramComplex D * beta_Complex. Applying H and hHG gives equality of complex coordinates; injectivity of the integer cast gives p = beta. This helper is actually invoked in component_charge. Only hHG is needed in this separation step, while the public theorem, original quotient, physical projection and bracket retain BOTH hHG and hGH and rank 26.")),
                    Paragraph(Text("Every nonzero component in the finite reconstruction therefore has charge beta and belongs to F_beta; every zero component belongs by the same submodule zero axiom. Finite-sum closure proves (c : C) ∈ F_beta, including beta = 0 and beta absent from S. The two helpers are private and have actual local consumers project_component and component_charge in this public proof.")),
                    Paragraph(Text("The substantive increment over the existing forward action is the converse on the entire literal physical image, using finite physical-component reconstruction and separation of every original integral charge. A future actual Weyl automorphism with its proved Cartan conjugation law could use this characterization to identify transformed charges. No such automorphism or downstream consumer of this public theorem is constructed in this package."))), DescribeRole.Theorem),
            Paragraph(Text("The original lattice-field suppliers retain Bakalov–Kac, Carnahan and Kytölä attribution. The BRST and current suppliers retain Becchi–Rouet–Stora–Tyutin, Kato–Ogawa and Lian–Zuckerman attribution. Mathlib supplies finite sums, quotient maps, complex linear algebra, matrix-vector identities and integer-cast injectivity; Batteries.Tactic.OpenPrivate supplies access to existing private declarations. No literature-novelty claim is made.")),
            Paragraph(Text("The Blueprint C# layout is taken from both sealed valid Scribe examples. StatementSource.WithoutFormula() and AssessedProvenance.FromRepo() follow their exact DSL convention; they confer no compilation or acceptance status on this source-only candidate. Native validation and repository enrollment remain obligations.")),
            Paragraph(Text("Mathematical suppliers: "), Ref("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTPhysicalChargeFiber"), Text("; "), Ref("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTPhysicalLie"), Text("; "), Ref("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTChargeCohomology"), Text("; "), Ref("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTNeutralPhysicalCartan"), Text("; "), Ref("D5/S3/VertexAlgebra/LatticeFiniteNegativeGeneration")))));
}
